import unittest
from candidate import greatest_common_divisor

class TestGreatestCommonDivisor(unittest.TestCase):
    def test_greatest_common_divisor_positive_numbers(self):
        self.assertEqual(greatest_common_divisor(3, 5), 1)

    def test_greatest_common_divisor_larger_number_first(self):
        self.assertEqual(greatest_common_divisor(25, 15), 5)

    def test_greatest_common_divisor_with_zero(self):
        with self.assertRaises(ZeroDivisionError):
            greatest_common_divisor(3, 0)

    def test_greatest_common_divisor_with_negative_numbers(self):
        self.assertEqual(greatest_common_divisor(-3, 5), 1)
        self.assertEqual(greatest_common_divisor(3, -5), 1)

    def test_greatest_common_divisor_with_non_integer_input(self):
        with self.assertRaises(TypeError):
            greatest_common_divisor(3.5, 5)
        with self.assertRaises(TypeError):
            greatest_common_divisor(3, 5.5)

    def test_greatest_common_divisor_with_non_numeric_input(self):
        with self.assertRaises(TypeError):
            greatest_common_divisor('a', 5)
        with self.assertRaises(TypeError):
            greatest_common_divisor(3, 'b')

    def test_greatest_common_divisor_with_same_numbers(self):
        self.assertEqual(greatest_common_divisor(5, 5), 5)

    def test_greatest_common_divisor_with_one_number(self):
        self.assertEqual(greatest_common_divisor(5, 1), 1)
        self.assertEqual(greatest_common_divisor(1, 5), 1)

if __name__ == '__main__':
    unittest.main()
